document.addEventListener("DOMContentLoaded",function(){const t=document.querySelector(".preloader");if(!t)return;const e=new FontFace("Quicksand","url(/fonts/quicksand/Quicksand-VariableFont_wght.ttf)");e.load().then(function(){document.fonts.add(e),t.classList.add("loaded"),document.querySelector("html").removeAttribute("style")}).catch(function(e){t.classList.add("loaded"),document.querySelector("html").removeAttribute("style")})});